/**
 * Order pricing calculator combining discounts and regional tax rules (Topological Level 1).
 */

import { best_discount } from "./discounts";

import { calculate_tax, round_currency } from "./tax_rules";

export function compute_discounted_subtotal(gross_subtotal: number, tier: string, coupon_code: string): number {
  if ((gross_subtotal <= 0.0)) {
    return 0.0;
  }
  let disc = best_discount(gross_subtotal, tier, coupon_code);
  return round_currency(Math.max(0.0, (gross_subtotal - disc)), 2);
}

export function compute_final_price(gross_subtotal: number, tier: string, coupon_code: string, region: string): number {
  let net_subtotal = compute_discounted_subtotal(gross_subtotal, tier, coupon_code);
  let tax = calculate_tax(net_subtotal, region);
  return round_currency((net_subtotal + tax), 2);
}

export function estimate_bulk_unit_price(unit_price: number, quantity: number): number {
  if (((unit_price <= 0.0) || (quantity <= 0))) {
    return 0.0;
  }
  if ((quantity >= 100)) {
    return round_currency((unit_price * 0.85), 2);
  }
  if ((quantity >= 25)) {
    return round_currency((unit_price * 0.92), 2);
  }
  if ((quantity >= 10)) {
    return round_currency((unit_price * 0.96), 2);
  }
  return round_currency(unit_price, 2);
}
